  Activity_100432_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n· Während der Aktivierung der “Hypnoschabe“-Aktivität können Schutzherren unendlich oft die vorgegebenen Teams mit Clementine verwenden, um die bestimmten Level zu erleben.\n· Während des Erlebens der Aktivitätslevel können die Erwecker im Team nicht angepasst werden.\n<Title:Aktivitätsbelohnungen>\n· Nach dem erstmaligen Abschluss der Levelherausforderung können im Aktivitätsfenster Testbelohnungen abgeholt werden."
  },
  Activity_100433_ActivityName = {
    Text = "Bischof der Salben"
  },
  Activity_100433_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n·Während des \"Benevolent Bishop\"-Events können Hüter systemvorgesehene Teams mit Salvador verwenden, um festgelegte Levels unbegrenzt oft zu erleben.\n·Beim Spielen von Event-Levels können Anpassungen am Erwachen im Teamaufbau nicht vorgenommen werden.\n<Title:Aktivitätsbelohnungen>\n·Nach erfolgreichem Abschluss einer Level-Herausforderung zum ersten Mal können Sie Versuchsbelohnungen über die Event-Schnittstelle beantragen."
  },
  Activity_116469_ActivityName = {
