  Activity_116470_ActivityName = {
    Text = "Die Nacht der Mitternachtssonne"
  },
  Activity_116470_ActivityPlot = {
    Text = "Sie kreuzten sich am Ende des Schicksals, die neu schwingende Uhr war bereits viel zu spät, nur das reumütige Herz schwor, alles Unreine in der Dunkelheit vollständig zu erleuchten."
