  Activity_116765_ActivityName = {
    Text = "Gravur des Aufbruchs"
  },
  Activity_116765_ActivityTips = {
    Text = "Aktionsregeln:\n1. Geheimnisträger können nach Abschluss bestimmter Aufgaben im “Eingravierter Aufbruch“ Belohnungen erhalten.\n2. Nach dem Freischalten der “Fortgeschrittenen Chronik“ können zusätzliche Belohnungen nach Abschluss von Aufgaben erhalten werden.\n3. Der Kauf der “Fortgeschrittenen Chronik“ ist zeitlich begrenzt, nach Ablauf der Frist kann sie nicht mehr gekauft werden. Bitte Schutzherr berücksichtigen, vor dem 3. November um 9:00 Uhr zu kaufen.\n4. Bitte beachten: Die “Fortgeschrittene Chronik“, die in dieser Aktion freigeschaltet wird, ist nur während dieser Aktion gültig. Schutzherr sollten verantwortungsbewusst konsumieren."
  },
  Activity_116765_BannerText = {
    Text = "Spezielle Reiseaktivität zeitlich begrenzt geöffnet!"
