  Activity_123151_ActivityTips = {
    Text = "<Title:Aktionsregeln>\n· Während der Aktivität “Herr der Begrabenen Knochen“ können Schutzherren die systemvorgeschlagene Gruppe mit Doresain unbegrenzt in den festgelegten Levels erleben. \n· Während des Erlebens der Aktionslevels kann der Erwecker in der Formation nicht angepasst werden. \n<Title:Aktionsbelohnungen>\n· Nach erstmaligem Abschluss der Level-Herausforderung können Belohnungen für das Testspiel im Aktionsinterface abgeholt werden."
  },
  Activity_123152_ActivityName = {
