  Activity_123152_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Apostle of the Sea\" Ereignisses können Hüter die vom System vordefinierten Teams, die Miryam enthalten, uneingeschränkt in bestimmten Stufen erleben.\n· Bei der Erfahrung der Ereignisstufen sind Anpassungen der Erwachenden in der Teamausstellung nicht erlaubt.\n<Title:Event Rewards>\n· Nach dem erfolgreichen Abschluss der Stufenherausforderung zum ersten Mal können die Spieler Versuchsprämien in der Ereignisschnittstelle beanspruchen."
  },
  Activity_123322_ActivityName = {
    Text = "Silberfrostreise"
  },
  Activity_123322_ActivityTips = {
    Text = "<Title:Aktionsregeln>\n1. Schutzherren können nach Abschluss bestimmter Aufgaben in der “Silberfrostreise“ Belohnungen erhalten.\n2. Die “Silberfrostreise“ endet am 12. Januar um 9:00 Uhr (GMT+8).\n3. Nach dem Freischalten der “Fortgeschrittenen Chronik“ können zusätzliche Belohnungen nach Abschluss der Aufgaben erhalten werden.\n4. Bitte beachten: Die in dieser Aktion freigeschaltete “Fortgeschrittene Chronik“ ist nur während dieser Aktion gültig. Schutzherren sollten verantwortungsbewusst konsumieren."
  },
