  Activity_124987_ActivityPlot = {
    Text = "Symptom: Hysterie, auch bekannt als hysterische Störung.\nIn eurer Ära ist es gleichbedeutend mit dem Tod.\n\nZum Glück sind die Wissenschaftler und Ermittler der Misaq gleichermaßen verrückt: Sie sind entschlossen, dieses Problem zu lösen"
