  Activity_126275_ActivityPlot = {
    Text = "Das Rad dreht sich sanft, spinnt sich unaufhörlich durch die Äonen. Tanze entlang der silbernen Fäden, o Große Weberin. Denn das Schicksal ist die Bühne, von der du niemals fliehen kannst.\nRichterin. Erlöserin. Herrin. Gefangene...\nVon dem Moment an, als du diese Bretter betratst, war die Rolle, die du spielen solltest, nicht mehr deine Wahl."
