  Activity_126365_ActivityTips = {
    Text = "Aktionsregeln:\n1. Schutzherr können nach Abschluss bestimmter Aufgaben in den Schicksalsarchiven Belohnungen erhalten.\n2. Die Aufgaben sind in Gruppen unterteilt, wobei nach Beginn der Aktion täglich eine Gruppe freigeschaltet wird.\n3. Nach Freigabe der Pilgerfahrt-Archive können nach Abschluss von Aufgaben zusätzliche Belohnungen erhalten werden.\n4. Bitte beachten: Die in dieser Aktion freigeschaltete Fortgeschrittene Chronik ist nur in dieser einen Archiv-Aktion gültig."
  },
  Activity_126366_ActivityName = {
