  Activity_126492_ActivityName = {
    Text = "Panlong Monologe"
  },
  Activity_126492_ActivityTips = {
    Text = "<Title: Alter Reich Mischbuch>\n· Diese zeitlich begrenzte Reise umfasst 8 Pakete, von denen das erste Paket direkt kostenlos abgerufen werden kann. Die Pakete 2 bis 8 müssen nach dem Kauf von „Alter Reich Mischbuch\" abgerufen werden. \n· Nach dem Kauf von „Alter Reich Mischbuch\" kann sofort die Belohnung des 2. Pakets abgeholt werden; die weiteren Pakete müssen nach einer bestimmten Wartezeit abgerufen werden. \n· Wenn Sie „Alter Reich Mischbuch\" vor dem 26. Januar um 9:00 Uhr kaufen, erhalten Sie zusätzlich Belohnungen: Exklusives Avatar „Wahre Form im Fächer\" und „Einladung des Unstofflichen\" ×10! Nach dem 26. Januar um 9:00 Uhr sind keine zeitlich begrenzten exklusiven Belohnungen mehr verfügbar. \n· Nach dem Kauf wird die Dauer dieser zeitlich begrenzten Reise dauerhaft. Nach dem Abrufen aller Pakete wird die Veranstaltung am nächsten Tag geschlossen. \n· Der Kauf von „Alter Reich Mischbuch\" ist zeitlich begrenzt, nach Ablauf kann es nicht mehr gekauft werden. Bitte Schutzherr berücksichtigen Sie den Kauf bis zum 23. Februar um 9:00 Uhr."
  },
  Activity_126492_BannerText = {
    Text = "Spezielle Reiseaktivität zeitlich begrenzt geöffnet!"
