  Activity_130176_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n·Während der Aktivität „Blühende Liebe\" können Geheimnisträger unendlich oft die festgelegten Levels mit dem systemeigenen Team, das Shaye enthält, ausprobieren. \n·Während des Erlebnisses der Aktivitätslevel kann der Erwecker im Team nicht angepasst werden. \n<Title:Aktivitätsbelohnungen>\n·Nach erstmaliger Erfüllung der Level-Herausforderung können im Aktivitätsinterface die Testbelohnungen abgeholt werden."
  },
  Activity_130376_ActivityName = {
