  Activity_130922_ActivityName = {Text = "Wirbel"},
  Activity_130922_ActivityTips = {
    Text = "<Title:Event–Regeln>\nWährend des Events „M- Muskus\" können Schutzherren die vom System voreingestellte Formation mit Mosk verwenden, um die vorgesehenen Level unbegrenzt oft zu spielen.\nBeim Spielen der Event–Level können die Erweckten Körper in der Formation nicht angepasst werden.\n<Title:Event–Belohnungen>\nNach dem erstmaligen Abschluss einer Level–Herausforderung können Probebelohnungen auf der Event–Oberfläche abgeholt werden."
