  Activity_131370_ActivityTips = {
    Text = "<Title:Eventübersicht>\n1. Nach Abschluss der vorgegebenen Archiv-Aufgaben können Schutzherren Belohnungen unter „Glücklicher Gewinner\" einfordern.\n2. „Glücklicher Gewinner\" endet am 6. April um 9:00 Uhr.\n3. Schalte die „Fortgeschrittene Chronik\" frei, um nach Abschluss der Aufgaben zusätzliche Belohnungen zu erhalten.\n4. Bitte beachte: Die in diesem Event freigeschaltete „Fortgeschrittene Chronik\" gilt nur für dieses Event. Schutzherren, bitte geht verantwortungsvoll mit euren Ressourcen um."
  },
