  Activity_131849_ActivityName = {
    Text = "ewige Erinnerung"
  },
  Activity_131849_ActivityTips = {
    Text = "<Title:ewige Erinnerung>\n\nDieses Zeitlich begrenzte Reise enthält 8 Geschenkpakete. Das erste Geschenkpaket kann direkt kostenlos abgeholt werden, während für die Geschenkpakete 2–8 der Kauf von „ewige Erinnerung\" erforderlich ist, bevor sie abgeholt werden können.\n\nNach dem Kauf von „ewige Erinnerung\" können die Belohnungen des 2. Geschenkpakets sofort abgeholt werden; für nachfolgende Geschenkpakete muss eine bestimmte Zeit abgewartet werden, bevor sie abgeholt werden können.\n\nWer „ewige Erinnerung\" vor 9:00 Uhr am 30. Mai kauft, erhält zusätzliche Belohnungen: exklusiver Avatar „Guten Appetit\" und „Einladung des Unstofflichen\" ×10! Nach 9:00 Uhr am 30. Mai werden die zeitlich begrenzten exklusiven Belohnungen nicht mehr gewährt.\n\nBitte beachten: „ewige Erinnerung\" ist bis zum 29. Juni, 9:00 Uhr, zum Kauf verfügbar."
  },
