  Activity_132331_ActivityName = {
    Text = "Dame in Rot"
  },
  Activity_132331_ActivityTips = {
    Text = "<Title:Event–Regeln>\nWährend des Events „Dame in Rot\" können Schutzherren die vom System voreingestellte Formation mit „Sorel\" verwenden, um die vorgesehenen Level unbegrenzt oft zu spielen.\nBeim Spielen der Event–Level können die Erweckten Körper in der Formation nicht angepasst werden.\n<Title:Event–Belohnungen>\nNach dem erstmaligen Abschluss einer Level–Herausforderung können die Probebelohnungen auf der Event–Oberfläche abgeholt werden."
  },
