  Activity_132333_ActivityPlot = {
    Text = "Im unendlichen Verlangen nach Wünschen erwacht es kurz aus seinem langen Schlaf und wirft einen echten Blick auf diese düstere Welt.\nIn der Ewigkeit des Lebens ist dieser Blick so flüchtig"
