  },
  Activity_139116_ActivityTips = {
    Text = "<Title:Eventregeln>\n·Hüter können Belohnungen aus dem „Verträumtes Rendezvous \" erhalten, nachdem sie bestimmte Aufgaben abgeschlossen haben.\n·Nach dem Freischalten der „Fortgeschrittene Chronik\" können zusätzliche Belohnungen nach Abschluss von Aufgaben beansprucht werden.\n·Es gibt diesmal ein Zeitlimit für den Kauf der „Fortgeschrittene Chronik \". Nach Ablauf der Frist kann sie nicht mehr gekauft werden. Bitte kaufe sie nach eigenem Ermessen vor dem 29. Juni, 9:00 Uhr(GMT+8).\n·Bitte beachte: Die während dieses Events freigeschaltete „Fortgeschrittene Chronik\" gilt nur für dieses Event. Hütern wird empfohlen, ihre Ausgaben mit Bedacht zu tätigen."
  },
