  Activity_139923_ActivityPlot = {
    Text = "Symphonie ist die Kunst des Webens, die Bahnen der verschiedenen Instrumente verflechten sich zu einem komplexen Muster.\nIn seinem Netz hat jede Note ihre Aufgabe.\nHöre zu, eine großartige Symphonie beginnt jetzt"
