  Activity_140082_ActivityPlot = {
    Text = "Sie singen ein unvergessliches Lied und begrüßen den unverlöschlichen Herrn. \nEr wird mit unzähligen Glanzlichtern vom höchsten Himmel herabsteigen und von ewigem Glanz erzählen. \nWenn Er kommt, bedeckt das bernsteinfarbene Licht die Welt. \nDies ist die Beerdigung, die Er der Welt schenkt."
