  Activity_140761_ActivityTips = {
    Text = "<Title:Event Rules>\n· Während des \"Kalte Licht\"-Ereignisses können Hüter auf systemvorgegebene Teams, die Kepler Sangan enthalten, zu bestimmten Stufen unbegrenzt oft zugreifen.\n· Bei der Erfahrung der Ereignisstufen sind Anpassungen der Erwachenen in der Teamanpassung nicht möglich.\n<Title:Event Rewards>\n· Nach dem ersten Erreichen einer Level-Herausforderung können Sie Probe-Belohnungen im Ereignisinterface beanspruchen."
  },
  Activity_140762_ActivityName = {Text = "Maioka"},
  Activity_140762_ActivityTips = {
    Text = "<Title:Aktionsregeln>\n· Während des Events \"Versiegelter 'Dawn'\" können Hüter vordefinierte Aufstellungen des Systems, die Mouchette enthalten, unendlich oft in den festgelegten Stufen erleben.\n· Bei der Erkundung der Aktionsstufen können keine Anpassungen an den Erweckern in der Aufstellung vorgenommen werden.\n<Title:Aktionsbelohnungen>\n· Nach der erstmaligen Absolvierung der Stufenherausforderung kannst du im Aktionsinterface Testbelohnungen beanspruchen."
  },
  Activity_140763_ActivityName = {
    Text = "Unbenanntes Gedicht"
  },
  Activity_140763_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Nameless Poem\"-Ereignisses können Hüter systempreset Teams nutzen, die Horla enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_140764_ActivityName = {
    Text = "Lord von Nekrovia"
  },
  Activity_140764_ActivityTips = {
    Text = "<Title:Ereignis Regeln>\n· Während des Ereignisses \"Herr der Beerdigungen\" können Hüter ein systemvorgegebenes Team, einschließlich Durusain, nutzen, um das angegebene Niveau unbegrenzt oft zu erleben.\n· Bei der Erfahrung der Ereignislevels können Anpassungen bei den Erweckern im Team nicht vorgenommen werden.\n<Title:Ereignis Belohnungen>\n· Nach dem ersten Abschluss der Level-Challenge können Sie auf der Ereignisoberfläche Testbelohnungen einfordern."
  },
