  Activity_141308_ActivityName = {
    Text = "Quelle des Abgrunds"
  },
  Activity_141308_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\nWährend der Aktivität „Quelle des Abgrunds\" können Schutzherren das vom System voreingestellte Team mit Pontos verwenden, um die angegebenen Level unbegrenzt oft zu erleben.\nBeim Erleben der Aktivitätslevel kann die Formation der Erwecker nicht angepasst werden.\n<Title:Aktivitätsbelohnungen>\nNach dem erstmaligen Bestehen einer Level-Herausforderung können Testspielbelohnungen in der Aktivitätsoberfläche abgeholt werden."
  },
  Activity_141460_ActivityName = {
    Text = "Divus: die Onyx-Feder"
  },
  Activity_141460_ActivityTips = {
    Text = "<Title:Event Rules>\n· Während des „Heiligen Schwarzflügels“-Ereignisses können Hüter das systemvorgeschlagene Team mit Castor verwenden, um bestimmte Stufen unbegrenzt zu erleben.\n· Die Awakeners in der Teamaufstellung können während der Ereignisstufen nicht angepasst werden.\n<Title:Event Rewards>\n· Nach dem erstmaligen Erreichen einer Stufenherausforderung kann eine Versuchsbelohnung im Ereignisschnittstelle beansprucht werden."
  },
  Activity_141462_ActivityName = {
    Text = "Schlummernder Herrscher"
  },
  Activity_141462_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Souverän des Schlafes\" Ereignisses können Hüter die systemvordefinierten Teams nutzen, die Tulu enthalten, um bestimmte Level unendlich zu erleben.\n·Bei der Erfahrung von Ereignislevels sind Anpassungen der Erwacher in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nach der erfolgreichen ersten Absolvierung der Level-Herausforderung können die Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_141464_ActivityName = {
    Text = "Die Obsidian-Matriarchin der Tausend-Federn"
  },
  Activity_141464_ActivityTips = {
    Text = "<Title:Veranstaltungsregeln>\n·Während des Events \"Obsidian-Matriarchin der Tausend-Fans\" können Hüter die vom System festgelegten Aufstellungen, die Xu enthalten, verwenden, um die festgelegten Stufen unbegrenzt oft zu erleben.\n·Bei der Erfahrung der Veranstaltungsstufen sind Anpassungen an den Erweckern in der Aufstellung nicht erlaubt.\n<Title:Veranstaltungsbelohnungen>\n·Nach erfolgreichem Abschluss der Stufenherausforderung zum ersten Mal kannst du Testbelohnungen über die Veranstaltungsoberfläche beanspruchen."
  },
  Activity_141466_ActivityName = {
    Text = "Nebenschauplätze werden kostenlos freigeschaltet"
