  Activity_141509_ActivityName = {
    Text = "Geheimnisvolle Reise"
  },
  Activity_141509_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n1, Nachdem Schutzherren die angegebenen Chronikaufgaben abgeschlossen haben, können sie in der „Geheimnisvollen Reise \" Belohnungen abholen.\n2, Die „Geheimnisvolle Reise\" endet am 27. Juli um 09:00 Uhr.\n3, Nach dem Freischalten der „Fortgeschrittenen Chronik \" können nach dem Abschließen von Aufgaben zusätzliche Belohnungen abgeholt werden.\n4, Bitte beachten: Die in dieser Aktivität freigeschaltete „Fortgeschrittene Chronik\" gilt nur für diese Aktivität. Schutzherren werden gebeten, nach eigenem Ermessen und vernünftig zu konsumieren."
  },
