  Activity_145458_ActivityName = {
    Text = "Leviathans Spiel"
  },
  Activity_145458_ActivityPlot = {
    Text = "Gierige Helden begehren unsterbliche Throne, verzweifelte Mütter suchen nach wiederauferstandenen Kindern, und wahnsinnige Hexenmeister hungern nach verbotenem Wissen – sie knien vor Ihm und flehen mit denselben Worten, die Es seit über zehntausend Jahren gehört hat.\nEs gewährt ihnen alles, nur um zuzusehen, wie sie alles verlieren. Es hat viertausend brutale Kämpfe bezeugt und bleibt dennoch unersättlich.\nDiesmal öffnen sich die Tore der Arena für dich. Komm, sag Es Ihm – was ist es, das du begehrst?\nSag Ihm, wie du dich von diesen viertausend gefallenen Seelen unterscheidest."
  },
