  Activity_148889_ActivityName = {
    Text = "Genesis-Ogier"
  },
  Activity_148889_ActivityTips = {
    Text = "<Title:Event–Regeln>\n·Während des Events „Ursprung Ogier\" können Schutzherren die vom System voreingestellten Formationen mit Ursprung Ogier verwenden, um die vorgesehenen Level unbegrenzt oft zu spielen.\n·Beim Spielen der Event–Level können die Erweckten Körper in der Formation nicht angepasst werden.\n<Title:Event–Belohnungen>\n·Nach dem erstmaligen Abschluss einer Level–Herausforderung können Probebelohnungen auf der Event–Seite abgeholt werden."
  },
  Activity_15788_ActivityName = {
    Text = "Alchemie-Ästhetik"
  },
  Activity_15788_ActivityTips = {
    Text = "Aktionsregeln:\n1. Während der „Alchemistische Ästhetik \"-Aktion erhalten Geheimnisträger nach Abschluss von „Gutscheinuntersuchung\" doppelte Belohnungen für bestimmte Materialien, bis zu 3 Mal täglich.\n2. Nicht genutzte doppelte Belohnungen werden am nächsten Tag um 9 Uhr(GMT+8) zurückgesetzt. Bitte rechtzeitig nutzen!"
  },
  Activity_15791_ActivityName = {
    Text = "Gnosis-Ausbruch"
  },
  Activity_15791_ActivityTips = {
    Text = "Eventregeln:\n1. Während des „Geistesblitz \"-Events werden nach Abschluss der „Präparatveredelung\" durch den Schutzherrn einige Materialbelohnungen verdoppelt, bis zu 3-mal pro Tag.\n2. Nicht genutzte Verdopplungschancen des Tages werden am nächsten Tag um 9:00(GMT+8) zurückgesetzt, also denkt daran, sie rechtzeitig zu nutzen～"
  },
  Activity_15793_ActivityName = {
    Text = "Regenstadt Schatten"
  },
  Activity_15793_ActivityPlot = {
    Text = "Jede Regennacht wird von Enttäuschung und Einsamkeit begleitet.\nManche verlieren die Liebe, manche die Würde.\nUnd manche verlieren ihren Kopf."
  },
  Activity_15793_ActivityTips = {
    Text = "<Title:Teilnahmebedingungen>\n·Schließe die \"Ermittlungsoperation\" 2-9 (Normal) ab, um teilzunehmen.\n<Title:Ermittlungsereignis>\n·Während des Ereigniszeitraums wird täglich ein neues Ermittlungsereignis in \"Schatten von Regenstadt\" gestartet. Hüter können ohne Verbrauch des Inventars freischalten und ermitteln. Nach Abschluss des Ermittlungsereignisses können Belohnungen wie Rein-Kern, Ermittlungsabzeichen und Erfahrung des Hüters erhalten werden.\n·Nach dem Ende des Ereignisses wird der Ermittlungsfortschritt von \"Schatten von Regenstadt\" gespeichert. Hüter können D-Juwelen im Spezialprotokoll verwenden, um nicht abgeschlossene Ermittlungen freizuschalten. Das Abschließen von nicht abgeschlossenen Ermittlungsereignissen während des Ereigniszeitraums gewährt ebenfalls Belohnungen, die mit denen während des Ereignisses übereinstimmen.<Title:Zeitlich begrenzte Belohnungen>\n·Zeitlich begrenzte Belohnungen sind während des Ereignisses verfügbar. Hüter können Rein-Kern, Philosophstein und Silberbelohnungen nach dem Abschluss von \"Schatten von Regenstadt\" (Normalmodus) und dem Abschluss von Ermittlungsereignissen in \"Schatten von Regenstadt\" erhalten! Zeitlich begrenzte Belohnungen sind nur während des Ereigniszeitraums verfügbar und können nach dem Ende des Ereignisses nicht mehr abgeschlossen oder beansprucht werden."
  },
  Activity_15793_UnlockConditionExplanation = {
    Text = "Schaltet frei nach Abschluss der \"Ermittlungsoperation\" 2-9 · Normal"
  },
  Activity_15797_ActivityName = {
    Text = "Schlummernder Herrscher"
  },
  Activity_15797_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Souverän des Schlafes\" Ereignisses können Hüter die systemvordefinierten Teams nutzen, die Tulu enthalten, um bestimmte Level unendlich zu erleben.\n·Bei der Erfahrung von Ereignislevels sind Anpassungen der Erwacher in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nach der erfolgreichen ersten Absolvierung der Level-Herausforderung können die Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_15805_ActivityName = {
    Text = "Nebelstadt Chronik"
  },
  Activity_15805_ActivityTips = {
    Text = "\nSpielregeln:\n1. Nach Abschluss der festgelegten Reiseaufgaben können Hüter Belohnungen im \"Fog City Journey\" einfordern.\n2. \"Fog City Journey\" ist dauerhaft geöffnet.\n3. Nach Freischaltung der \"Fortgeschrittenen Reise\" können Hüter zusätzliche Belohnungen beim Abschluss von Aufgaben erhalten.\n4. Bitte beachten: Die im Rahmen dieses Ereignisses freigeschaltete \"Fortgeschrittene Reise\" ist nur während dieses Ereignisses gültig. Hüter werden geraten, dies vernünftig zu nutzen."
  },
