  },
  Activity_15821_ActivityTips = {
    Text = "Eventregeln:\n1. Schutzherren können nach dem täglichen Login in „Schülergeschenk \" tägliche Anmeldebelohnungen erhalten.\n2. Belohnungen werden nacheinander basierend auf den kumulierten Anmeldetagen des Schutzherren freigeschaltet. Tägliche Anmeldebelohnungen werden um 9:00(GMT+8) aktualisiert."
  },
