  Activity_15828_ActivityName = {
    Text = "Einführungszeremonie"
  },
  Activity_15828_ActivityTips = {
    Text = "\nEreignisregeln:\n1. Hüter können Belohnungen bei der \"Einführungszeremonie\" sammeln, wenn ihr Untersuchungslevel 5/15/25/35/45/55 erreicht.\n2. Erfahrungen des Hüters können durch Untersuchungslevels und Zwischenspiele erhalten werden."
