  Activity_20344_ActivityTips = {
    Text = "\nEreignis Regeln:\n1. Nach Abschluss der festgelegten Reiseaufgaben können Hüter Belohnungen in \"Kein Licht Anfangsansicht\" beanspruchen.\n2. \"Kein Licht Anfangsansicht\" ist dauerhaft geöffnet."
