  Activity_20685_ActivityTips = {
    Text = "Eventregeln:\n1. Während des „Aufstiegsszene \"-Events werden nach Abschluss des „Organisches Residuum\" durch den Schutzherrn einige Materialbelohnungen verdoppelt, bis zu 3-mal pro Tag.\n2. Nicht genutzte Verdopplungschancen des Tages werden am nächsten Tag um 9:00(GMT+8) zurückgesetzt, also denkt daran, sie rechtzeitig zu nutzen～"
  },
  Activity_20686_ActivityName = {
    Text = "Intensives Training"
  },
  Activity_20686_ActivityTips = {
    Text = "Aktivitätsregeln:\n1. Während der „Starken Spezialausbildung \" wird die Materialbelohnung für Hüter, die die „Ruine von Bonape\" durchspielen, teilweise verdoppelt, bis zu 3 Mal täglich. \n2. Unbenutzte doppelte Belohnungsschancen des Tages werden um 9 Uhr(GMT+8) am nächsten Tag zurückgesetzt. Bitte denken Sie daran, rechtzeitig zu verwenden!"
  },
  Activity_20687_ActivityName = {
    Text = "Intensives Training"
  },
  Activity_20687_ActivityTips = {
    Text = "Aktivitätsregeln:\n1. Während der „Starken Spezialausbildung \" wird die Materialbelohnung für Hüter, die die „Chaosgruppe\" durchspielen, teilweise verdoppelt, bis zu 3 Mal täglich. \n2. Unbenutzte doppelte Belohnungsschancen des Tages werden um 9 Uhr(GMT+8) am nächsten Tag zurückgesetzt. Bitte denken Sie daran, rechtzeitig zu verwenden!"
  },
  Activity_20688_ActivityName = {
