  },
  Activity_20689_ActivityName = {
    Text = "Edify-Performance"
  },
  Activity_20689_ActivityTips = {
    Text = "Eventregeln:\n1. Während des „Aufstiegsszene \"-Events werden nach Abschluss des „Meerestiefenresiduum\" durch den Schutzherrn einige Materialbelohnungen verdoppelt, bis zu 3-mal pro Tag.\n2. Nicht genutzte Verdopplungschancen des Tages werden am nächsten Tag um 9:00(GMT+8) zurückgesetzt, also denkt daran, sie rechtzeitig zu nutzen～"
  },
  Activity_20690_ActivityName = {
    Text = "Edify-Performance"
