  Activity_20690_ActivityTips = {
    Text = "Eventregeln:\n1. Während des „Aufstiegsszene \"-Events werden nach Abschluss des „trübes Nachbild\" durch den Schutzherrn einige Materialbelohnungen verdoppelt, bis zu 3-mal pro Tag.\n2. Nicht genutzte Verdopplungschancen des Tages werden am nächsten Tag um 9:00(GMT+8) zurückgesetzt, also denkt daran, sie rechtzeitig zu nutzen～"
  },
  Activity_20691_ActivityName = {
    Text = "Schädeljägerin"
  },
  Activity_20691_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Skull Huntress\"-Ereignisses können Hüter systempreset Teams nutzen, die Narzisse enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_21502_ActivityName = {
    Text = "Apostel des Meeres"
  },
  Activity_21502_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Apostle of the Sea\" Ereignisses können Hüter die vom System vordefinierten Teams, die Miryam enthalten, uneingeschränkt in bestimmten Stufen erleben.\n· Bei der Erfahrung der Ereignisstufen sind Anpassungen der Erwachenden in der Teamausstellung nicht erlaubt.\n<Title:Event Rewards>\n· Nach dem erfolgreichen Abschluss der Stufenherausforderung zum ersten Mal können die Spieler Versuchsprämien in der Ereignisschnittstelle beanspruchen."
  },
  Activity_21781_ActivityName = {
    Text = "Lehrplan-Auswahlbox"
  },
  Activity_21781_ActivityPlot = {
    Text = "Vollständig die Mission, um einen bestimmten Erwecker aus \"Reichs-Studie\" oder ein bestimmtes Rad des Schicksals aus \"Rotations-Aspekt\" auszuwählen!"
  },
  Activity_21781_ActivityTips = {
    Text = "Eventregeln:\n1. Das Ansammeln von 50 Erweckungen, 3 Tage Anmeldung und 7 Tage Anmeldung gewähren „Protoparadies\"-Belohnungen. „Protoparadies\" kann unter „Vorräte: Verbrauchsgüter\" verwendet werden. Bei Verwendung kannst du 1 bestimmten Erweckten Körper aus „Grenzgebietstudium\" zur Erweckung auswählen.\n2. Das Ansammeln von 300 Erweckungen, 1000 Erweckungen und 30 Tage Anmeldung gewähren „Drehbuch\"-Belohnungen. „Drehbuch\" kann unter „Vorräte: Verbrauchsgüter\" verwendet werden. Bei Verwendung kannst du 1 bestimmtes Schicksrad aus „Drehender Aspekt\" erhalten."
  },
  Activity_22367_ActivityName = {
    Text = "Gnosis-Ausbruch"
  },
  Activity_22367_ActivityTips = {
    Text = "Eventregeln:\n1. Während des Events „Geistesblitz \" erhalten Schutzherren eine zusätzliche Belohnung von 50 %(ausgenommen Schutzmeister-Erfahrung), wenn sie in „Präparatveredelung\" ermitteln oder Wiederholen, ohne tägliches Limit."
  },
  Activity_23671_ActivityName = {
    Text = "Tiefen-Tauchduell"
  },
  Activity_23671_ActivityPlot = {
    Text = "Aktivitätszeitraum verdoppelt die Erfahrungen des Hüters, die durch „phantasmaler Sturzflug\" und „Traphase\" erhalten werden, mit einer täglichen Obergrenze von 480 Punkten"
  },
  Activity_23671_ActivityTips = {
    Text = "\nRegeln für das Ereignis:\n1. Während des Ereignisses \"Phantasma-Tauchgang und Traphase\" erhält der Hüter die doppelte Erfahrung des Hüters aus \"Phantasma-Tauchgang\" und \"Traphase\", mit einem täglichen Limit von 480 Punkten. Wenn das Kernthema ebenfalls freigeschaltet ist, wird die durch diesen Weg gewonnene Erfahrung des Hüters erneut verdoppelt, wobei das tägliche Limit bei 480 Punkten bleibt.\n2. Alle ungenutzten doppelten Erfahrungen des Hüters für den Tag setzen sich am nächsten Tag um 9:00 Uhr (GMT+8) zurück, also denke daran, sie rechtzeitig zu nutzen, Hüter~"
  },
  Activity_23693_ActivityName = {
    Text = "Blasser Nachkomme"
  },
  Activity_23693_ActivityPlot = {
    Text = "Der Legende nach existiert unter Lentiniën eine einzige Tür.\nSie führt in das Reich der Ascheherrin..."
  },
  Activity_23693_ActivityTips = {
    Text = "<Title:Teilnahmebedingungen>\n· Die Teilnahme ist nach Abschluss des normalen Modus des Bewusstseinswanderns \"Wunsch des Ritters\" möglich.\n<Title:Ermittlungsereignisse>\n· Während des Eventzeitraums wird täglich ein neues Ermittlungsevent in \"Blasser Nachkomme\" gestartet. Hüter können Ermittlungseignisse freischalten und durchführen, ohne Inventar zu verbrauchen, und das Abschließen von Ermittlungseignissen bringt Belohnungen wie reine Kerne, Ermittlungsabzeichen und Erfahrungen des Hüters.\n· Nach dem Ende des Events wird der Fortschritt der Ermittlungen in \"Blaser Nachkomme\" gespeichert. Hüter können gesperrte Ermittlungen im Bewusstseinswandern freischalten, indem sie D-Juwelen konsumieren, und das Abschließen von unvollendeten Ermittlungseignissen während des Eventzeitraums bringt ebenfalls Ermittlungsbelohnungen, die mit den während des Events verfügbaren übereinstimmen.<Title:Zeitlich begrenzte Belohnungen>\n· Zeitlich begrenzte Belohnungen sind während des Eventzeitraums verfügbar. Hüter können nach Abschluss des normalen Modus von \"Blaser Nachkomme\" und dem Abschluss der Ermittlungseignisse die Dunkle Sperre und Silberbelohnungen erhalten! Zeitlich begrenzte Belohnungen sind nur während des Events verfügbar und können nach dessen Ende nicht mehr abgeschlossen oder beansprucht werden."
  },
  Activity_23693_UnlockConditionExplanation = {
    Text = "Vollständig das umherirrende \"Ritter-Wunsch\", um danach freizuschalten"
  },
  Activity_23723_ActivityName = {
    Text = "Der Sturm naht"
  },
  Activity_23723_ActivityTips = {
    Text = "Eventregeln:\n1. Während des Events ist Ermittlungseinsatz Kapitel 5 vorübergehend geschlossen. Die Posse „Ewige Besessenheit \" kann vorübergehend durch Abschluss von Ermittlungseinsatz Kapitel 4 erhalten werden.\n2. Nach Ende des Events wird Ermittlungseinsatz Kapitel 5 wieder geöffnet, und die Posse „Ewige Besessenheit\" erfordert erneut den Abschluss von Ermittlungseinsatz Kapitel 5.\n3. Zusätzlich bleiben alle zuvor verdienten Kapitel-5-Erreichungsbelohnungen, Level-Erfolge, Erkundungsbelohnungen und Abschlussbelohnungen erhalten. Bei der Wiedereröffnung(derzeit geplant für den 27. Dezember) wird der abgeschlossene Fortschritt so weit wie möglich übernommen, sodass nichts wiederholt werden muss."
  },
  Activity_23870_ActivityName = {
    Text = "Traphase-Schlussfolgerung"
  },
  Activity_23870_ActivityTips = {
    Text = "Eventregeln:\n1. Schließe während des Events Eventmissionen ab, um Belohnungen zu erhalten.\n2. Nach dem Ende des Events können nicht abgeholte Eventbelohnungen nicht mehr beansprucht werden. Hüter, bitte denkt daran, sie rechtzeitig abzuholen～"
  },
