  Activity_24036_ActivityPlot = {
    Text = "Aktivitätszeitraum verdoppelt die Erfahrungen des Hüters, die durch „phantasmaler Sturzflug\" und „Traphase\" erhalten werden, mit einer täglichen Obergrenze von 480 Punkten"
  },
  Activity_24036_ActivityTips = {
    Text = "\nRegeln für das Ereignis:\n1. Während des Ereignisses \"Phantasma-Tauchgang und Traphase\" erhält der Hüter die doppelte Erfahrung des Hüters aus \"Phantasma-Tauchgang\" und \"Traphase\", mit einem täglichen Limit von 480 Punkten. Wenn das Kernthema ebenfalls freigeschaltet ist, wird die durch diesen Weg gewonnene Erfahrung des Hüters erneut verdoppelt, wobei das tägliche Limit bei 480 Punkten bleibt.\n2. Alle ungenutzten doppelten Erfahrungen des Hüters für den Tag setzen sich am nächsten Tag um 9:00 Uhr (GMT+8) zurück, also denke daran, sie rechtzeitig zu nutzen, Hüter~"
  },
