  Activity_44706_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n·Während des \"Benevolent Bishop\"-Events können Hüter systemvorgesehene Teams mit Salvador verwenden, um festgelegte Levels unbegrenzt oft zu erleben.\n·Beim Spielen von Event-Levels können Anpassungen am Erwachen im Teamaufbau nicht vorgenommen werden.\n<Title:Aktivitätsbelohnungen>\n·Nach erfolgreichem Abschluss einer Level-Herausforderung zum ersten Mal können Sie Versuchsbelohnungen über die Event-Schnittstelle beantragen."
  },
  Activity_44716_ActivityName = {
    Text = "Schlummernder Herrscher"
  },
  Activity_44716_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Souverän des Schlafes\" Ereignisses können Hüter die systemvordefinierten Teams nutzen, die Tulu enthalten, um bestimmte Level unendlich zu erleben.\n·Bei der Erfahrung von Ereignislevels sind Anpassungen der Erwacher in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nach der erfolgreichen ersten Absolvierung der Level-Herausforderung können die Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_45664_ActivityName = {
    Text = "Der Fall eines Riesen"
  },
  Activity_45664_ActivityPlot = {
    Text = "Der endlose Ozean, die brennende Sonne, ein verbannter philistinischer Held und sein einziger Begleiter.\nDies ist eine Geschichte über das „Suchen\"."
  },
  Activity_45664_ActivityTips = {
    Text = "<Title:Teilnahmebedingungen>\nSchließe die Bewusstseinsdrift „Des Ritters Wunsch\" im Normalmodus ab, um teilzunehmen.\n<Title:Ermittlungsereignis>\nWährend des Eventzeitraums können Schutzherren Ermittlungen freischalten und durchführen, ohne Inventar zu verbrauchen. Nach Abschluss des Ermittlungsereignisses können Belohnungen wie Unbefleckter Kern, Ermittlungswappen und Schutzmeister-Erfahrung erhalten werden.\nNach Ende des Events bleiben der Freischaltzustand und der Ermittlungsfortschritt von „Der Fall eines Riesen\" erhalten. Das Abschließen nicht abgeschlossener Ermittlungsereignisse während des Eventzeitraums gewährt ebenfalls Belohnungen, die mit denen während des Events übereinstimmen; falls während des Eventzeitraums nicht freigeschaltet, kann die Freischaltung nach Ende des Events durch Verbrauch von Realitätsanfang *3 erfolgen.<Title:Zeitlich begrenzte Belohnungen>\nWährend des Events sind zeitlich begrenzte Belohnungen verfügbar. Schutzherren können Dimensionskristall und Silber als Belohnungen erhalten, nachdem sie „Der Fall eines Riesen\" im Normalmodus abgeschlossen und die Ermittlungsereignisse von „Der Fall eines Riesen\" beendet haben! Zeitlich begrenzte Belohnungen sind nur während des Eventzeitraums verfügbar und können nach Ende des Events nicht mehr abgeschlossen oder eingefordert werden."
  },
  Activity_45664_UnlockConditionExplanation = {
    Text = "Vollständig das umherirrende \"Ritter-Wunsch\", um danach freizuschalten"
  },
  Activity_46167_ActivityName = {
    Text = "Dissoziativer Patient: Chaos"
  },
  Activity_46167_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n·Während des \"Splinter Patient: Chaos\"-Events können Hüter systemvorgesehene Teams mit \"24\" verwenden, um festgelegte Levels unbegrenzt oft zu erleben.\n·Beim Spielen von Event-Levels können Anpassungen am Erwachen im Teamaufbau nicht vorgenommen werden.\n<Title:Aktivitätsbelohnungen>\n·Nach erfolgreichem Abschluss einer Level-Herausforderung zum ersten Mal können Sie Versuchsbelohnungen über die Event-Schnittstelle beantragen."
  },
  Activity_46168_ActivityName = {
