  Activity_48825_ActivityPlot = {
    Text = "Schutzherren können 1 der folgenden limitierten Erweckten Körper auswählen und erwecken!"
  },
  Activity_48825_ActivityTips = {
    Text = "<Title:Übersicht>\nOhne eure eifrige Wachsamkeit wäre Misaq vielleicht für immer in der langen Nacht begraben geblieben. Nun haben wir unser Versprechen eingelöst, Strapazen durchquert und den Moment des Halbjahres–Jubiläums erreicht. Dafür wird euch die Schulkatze ein besonderes Geschenk überreichen, als Zeichen der Wertschätzung für eure Begleitung die ganze Zeit über.\n\n<Title:Eventregeln>\nWährend des Events kann jeder Schutzherr 1 Erweckten Körper aus 8 limitierten SSR–Erweckten Körpern auswählen, darunter Tulu, Daffodil, Sorel, Lily, Murphy, Wanda, Salvador und „24„.\nWenn ein Schutzherr einen bereits erweckten Erweckten Körper auswählt, wird dieser in den entsprechenden Splitter*1 und Ursprüngliche Abscheidung*50 umgewandelt; wenn die Erwachen–Stufe des entsprechenden Erweckten Körpers voll ist, wird er in Seelenkernsplitter*1 und Ursprüngliche Abscheidung*150 umgewandelt."
  },
  Activity_48825_BannerText = {
    Text = "Freier Begrenzter Erwacher"
  },
  Activity_48826_ActivityName = {
    Text = "Dämmerung und Morgengrauen"
  },
  Activity_48826_ActivityPlot = {
    Text = "Logge dich täglich ein, um ein limitiertes SSR-Gedenkrad des Schicksals „Dämmerung und Morgengrauen\" zu erhalten – insgesamt bis zu 16 Stück!"
  },
  Activity_48826_ActivityTips = {
    Text = "<Title:Introduction>\nDies ist ein Gedicht, das den Spielern gewidmet ist, über Ideale, über Glauben und über die gemeinsam verbrachte Zeit. Möge das aufrichtige Herz niemals aufhören zu schlagen, und möge der Silberne Schlüssel den Weg nach vorne weisen.\n\n<Title:Event Rules>\n· Während des Events können Hüter sich täglich einloggen, um das erinnerungswürdige limitierte SSR-Rad des Schicksals \"Polarnacht und Tagesanbruch\" von \"Polarnacht und Tagesanbruch\" zu erhalten, insgesamt bis zu 16 Ansprüche.\n· Die Belohnungen werden basierend auf den kumulierten täglichen Logins der Hüter nacheinander freigeschaltet, und die täglichen Login-Belohnungen werden um 9 Uhr (GMT+8) zurückgesetzt."
  },
  Activity_48826_BannerText = {
    Text = "Kostenloses limitiertes SSR–Schicksrad"
  },
  Activity_48827_ActivityName = {
    Text = "Silber im Hut"
  },
  Activity_48827_ActivityPlot = {
    Text = "Laut unvollständigen Statistiken wurde der Hut der Schulkatze in den letzten sechs Monaten Tausende Male von Schülern gestreichelt, wodurch viele winzige, unbemerkte Silber zu Boden gefallen sind. Dies hat das Reinigungspersonal beunruhigt. Daher hat die Schule diese Silber eingesammelt und gereinigt und im Fundbüro aufbewahrt. Besitzer sollten sie umgehend abholen."
  },
  Activity_48827_ActivityTips = {
    Text = "<Title:Übersicht>\nLaut unvollständigen Statistiken haben Schüler in den letzten sechs Monaten Tausende Fotos vom Hut der Schulkatze gemacht. Viele kleine und unauffällige Silberstücke sind zu Boden gefallen, wurden aber nicht beansprucht. Die für die Reinigung zuständigen Hausmeister sind darüber ziemlich beunruhigt. Die Schule hat diese Silberstücke nun eingesammelt, gründlich gereinigt und im Fundbüro aufbewahrt. Rechtmäßige Besitzer werden gebeten, sich zu melden und sie abzuholen.\n\n<Title:Ereignis-Regeln>\nWährend des Ereignisses können Hüter sich täglich einloggen, um 1000 Silber aus „Silber im Hut„ zu erhalten, mit maximal 5 Abholungen.\nBelohnungen werden nacheinander basierend auf den kumulativen Logins der Hüter freigeschaltet, und die täglichen Login-Belohnungen werden um 9 Uhr (GMT+8) aktualisiert."
  },
