  Activity_56428_ActivityPlot = {
    Text = "Im Spiegelbild der Tiefsee zerfällt der Traum des Königs, das Reich der Götter ist verfallen.\nSie kommt aus alten Träumen, tritt in die Ruinen der Zukunft.\nSie fragt den Abgrund, der Abgrund schweigt.\nSie opfert dem Abgrund, und nur sie selbst antwortet"
