  Activity_61156_ActivityName = {
    Text = "Endspieldurchgang"
  },
  Activity_61156_ActivityTips = {
    Text = "Ereignis Regeln:\n1. Nach Abschluss der angegebenen Hüteraufgaben können Belohnungen im \"Final Journal\" beansprucht werden.\n2. Das \"Final Journal\" ist dauerhaft verfügbar.\n3. Schalte das \"Advanced Journal\" frei, um zusätzliche Belohnungen nach Abschluss der Aufgaben zu erhalten.\n4. Hinweis: Das während dieses Ereignisses freigeschaltete \"Advanced Journal\" ist nur für die Dauer dieses Ereignisses gültig. Hüter werden geraten, klug auszugeben."
  },
  Activity_61369_ActivityName = {
    Text = "Progressiver Rhythmus"
  },
  Activity_61369_ActivityPlot = {
    Text = "Schutzherren können eines der folgenden limitierten Schicksräder auswählen und kostenlos erwecken!"
  },
  Activity_61369_ActivityTips = {
    Text = "<Title:Übersicht>\nIm mysteriösen Schwarzen Tümpel, wo Wolken der Intrige wirbeln, dreht sich das Schicksrad immer wieder. Geleitet von Hamelns Musik harmonieren unzählige Melodien zum Schicksrad deiner Reise. Möge ihre Hilfe dich begleiten bis zur letzten Note der abschließenden Symphonie.\n\n<Title:Eventregeln>\nWährend des Events kannst du dich einen Tag einloggen, um eines der folgenden 12 limitierten Schicksräder auszuwählen und zu erwecken, darunter: Hymne des Herrschers, Kostbare Sammlung, Im Namen der Rose, Gnade durch Schmerz, Verborgene Geburt, Edikt der Königin, Schrifttafel, Verstümmelungsrückprall, Macht der Frommen, Der letzte Vers, Barmherzige Pflege und Stunde des Glücks."
  },
  Activity_61369_BannerText = {
    Text = "Erhalte ein limitiertes Schicksrad kostenlos"
  },
  Activity_61370_ActivityName = {Text = "Silberherz"},
  Activity_61370_ActivityPlot = {
    Text = "Logge dich täglich ein, um das limitierte Gedenk–SSR–Schicksrad „Reines Silberherz\" zu beanspruchen, insgesamt bis zu 16!"
  },
  Activity_61370_ActivityTips = {
    Text = "<Title:Einführung>\nEgal, wie die Welt auf den Kopf gestellt wird, solange jeder sein ursprüngliches, reines Silberherz bewacht, wird die Geschichte unweigerlich in Zyklen verlaufen, und neues Leben wird auf der verwüsteten Erde wiedergeboren.\n\n<Title:Ereignis Regeln>\n· Während des Ereignisses können Hüter sich täglich einloggen, um das limitierte SSR Rad des Schicksals „Reines Silberherz“ zu beanspruchen, insgesamt 16 Ansprüche.\n·Belohnungen werden der Reihenfolge nach freigeschaltet, entsprechend den kumulierten Logins der Hüter, und die täglichen Login-Belohnungen werden um 9 Uhr (GMT+8) zurückgesetzt"
  },
  Activity_61370_BannerText = {
    Text = "Kostenloses limitiertes SSR–Schicksrad"
  },
  Activity_61371_ActivityName = {
    Text = "Gebete der Sechsflügelige"
  },
  Activity_61371_ActivityPlot = {
    Text = "Inmitten der Turbulenzen des Schwarzen Tümpels wurde Silber aus unendlichen Dimensionen durch Dimensionsrisse an seine Ufer verstreut. Tawil sammelte es sorgfältig auf und legte es in eine Ecke des Schwarzen Tümpels. Obwohl dieses Silber die Verbreitung der Auflösung nicht aufhalten kann, werden die Gefühle und Empfindungen, die es in sich birgt, für immer strahlend leuchten."
  },
  Activity_61371_ActivityTips = {
    Text = "<Title:Übersicht>\nInmitten der Turbulenzen des Schwarzen Tümpels liegt Silber, das durch Dimensionsrisse aus unendlichen Dimensionen verstreut wurde, am Rand des Schwarzen Tümpels. Tawil sammelt es sorgfältig auf und legt es in eine Ecke des Schwarzen Tümpels. Obwohl dieses Silber die Verbreitung der Auflösung nicht aufhalten kann, werden die Erinnerungen und Gefühle, die es in sich birgt, stets strahlend leuchten.\n\n<Title:Eventregeln>\nWährend des Events können sich Schutzherren täglich einloggen, um 1000 Silber während der Aktivität zu erhalten, mit maximal 6 Abholungen.\nAm 7. kumulativen Login–Tag können Schutzherren direkt den limitierten Erweckten Körper „Tavi„ beanspruchen!\nBelohnungen werden nacheinander basierend auf den kumulativen täglichen Logins der Schutzherren freigeschaltet, und die täglichen Login–Belohnungen werden um 9 Uhr (GMT+8) aktualisiert."
  },
  Activity_61371_BannerText = {
    Text = "Logge dich ein und erhalte jede Menge Silber"
  },
