  Activity_65387_ActivityName = {
    Text = "Entschuldigung der Schulkatze"
  },
  Activity_65387_ActivityPlot = {
    Text = "Aufgrund kürzlicher Schwachstellen in den Schutzmaßnahmen der Schule nehmen <Del:„Temporärer Text, Roter Punkt\"> Auflösungs–Belästigungsvorfälle auf dem Campus zu und verursachen den Schülern große Unannehmlichkeiten. Daher hat die Schulverwaltung mehrere Versorgungspunkte eingerichtet, um Materialien als Entschädigung zu verteilen. (Angesichts der Verantwortung für die Versäumnisse im Anlagenmanagement werden sämtliche Versorgungsmaterialien diesmal vollständig von der Schulkatze transportiert.)"
  },
  Activity_65387_ActivityTips = {
    Text = "<Title:Übersicht>\nIn letzter Zeit kam es aufgrund von Lücken in den Schutzmaßnahmen der Schule zu einer zunehmenden Anzahl von <Del>„Temporärer Text, roter Punkt„> Auflösungsvorfällen, die den Campus stören und den Schülern erhebliche Unannehmlichkeiten bereiten. Daher hat die Schulverwaltung mehrere Versorgungspunkte eingerichtet, um Vorräte als Entschädigung zu verteilen. (Aufgrund der Verantwortung für Fehler im Anlagenmanagement wird die Verteilung der Materialien vollständig von der Schulkatze übernommen.)\n\n<Title:Eventregeln>\nWährend des Events können sich Schutzherren täglich einloggen, um 500 Silber aus „Die Entschuldigung der Schulkatze„ zu beanspruchen, mit maximal 5 Abholungen.\nBelohnungen werden nacheinander basierend auf den kumulativen täglichen Logins der Schutzherren freigeschaltet, und die täglichen Login–Belohnungen werden um 9 Uhr (GMT+8) aktualisiert."
  },
  Activity_65387_BannerText = {
    Text = "Logge dich ein und erhalte Silber"
  },
  Activity_65502_ActivityName = {
    Text = "Fortschrittliche Melodie: Duett"
  },
  Activity_65502_ActivityPlot = {
    Text = "Schutzherren können eines der folgenden limitierten Schicksräder auswählen und kostenlos erwecken!"
  },
  Activity_65502_ActivityTips = {
    Text = "<Title:Übersicht>\nIm mysteriösen Schwarzen Tümpel, wo Wolken der Intrige wirbeln, dreht sich das Schicksrad immer wieder. Geleitet von Hamelns Musik harmonieren unzählige Melodien zum Schicksrad deiner Reise. Möge ihre Hilfe dich begleiten bis zur letzten Note der abschließenden Symphonie.\n\n<Title:Eventregeln>\nWährend des Events kannst du dich einen Tag einloggen, um eines der folgenden 12 limitierten Schicksräder auszuwählen und zu erwecken, darunter: Hymne des Herrschers, Kostbare Sammlung, Im Namen der Rose, Gnade durch Schmerz, Verborgene Geburt, Edikt der Königin, Schrifttafel, Verstümmelungsrückprall, Macht der Frommen, Der letzte Vers, Barmherzige Pflege und Stunde des Glücks."
  },
  Activity_65502_BannerText = {
    Text = "Erhalte ein limitiertes Schicksrad kostenlos"
  },
  Activity_65521_ActivityName = {
    Text = "Ermittlungsversorgungsbox"
  },
  Activity_65521_ActivityPlot = {
    Text = "Erkundungsversorgung, bereitgestellt vom Misaq-Verwaltungsbüro. Von Alistair aus dem Treibgut des Schwarzen Beckens verfeinert."
  },
  Activity_65949_ActivityName = {
    Text = "Geschenke von Mythag"
