  Activity_67735_ActivityPlot = {
    Text = "Träume offenbaren die Sehnsüchte des Unterbewusstseins. Wer in Träumen wandelt, wird schließlich vom Meer der Begierde umgarnt und zu einem Apostel der Lust, es sei denn..."
