  Activity_71325_ActivityName = {
    Text = "Unbenanntes Gedicht"
  },
  Activity_71325_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Nameless Poem\"-Ereignisses können Hüter systempreset Teams nutzen, die Horla enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_71329_ActivityName = {
    Text = "Blüte des Schlammes"
  },
  Activity_71329_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Mire Flower\"-Ereignisses können Hüter systempreset Teams nutzen, die Lily enthalten, um festgelegte Levels unendlich zu erleben.\n·Bei den Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_71743_ActivityName = {
    Text = "Schädeljägerin"
  },
  Activity_71743_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Skull Huntress\"-Ereignisses können Hüter systempreset Teams nutzen, die Narzisse enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_71744_ActivityName = {
    Text = "Bischof der Salben"
  },
  Activity_71744_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n·Während des \"Benevolent Bishop\"-Events können Hüter systemvorgesehene Teams mit Salvador verwenden, um festgelegte Levels unbegrenzt oft zu erleben.\n·Beim Spielen von Event-Levels können Anpassungen am Erwachen im Teamaufbau nicht vorgenommen werden.\n<Title:Aktivitätsbelohnungen>\n·Nach erfolgreichem Abschluss einer Level-Herausforderung zum ersten Mal können Sie Versuchsbelohnungen über die Event-Schnittstelle beantragen."
  },
  Activity_71745_ActivityName = {
    Text = "Dame in Rot"
  },
  Activity_71745_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Red Lady\"-Ereignisses können Hüter systempreset Teams nutzen, die Sorel enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
  },
  Activity_71746_ActivityName = {
    Text = "Lady der Tiefen"
  },
  Activity_71746_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Aequor Lady\" Ereignisses können Hüter die vom System vordefinierten Teams, die Murphy enthalten, uneingeschränkt in bestimmten Stufen erleben.\n· Während der Erfahrung der Ereignisstufen sind Anpassungen der Erwachenden in der Teamausstellung nicht erlaubt.\n<Title:Event Rewards>\n· Nach dem erfolgreichen Abschluss der Stufenherausforderung zum ersten Mal können die Spieler Versuchsprämien in der Ereignisschnittstelle beanspruchen."
  },
