  Activity_76217_ActivityTips = {
    Text = "Aktivitätsregeln: \n1. Geheimnisträger können nach Abschluss der vorgegebenen Reise-Aufgaben im “Reise-Modus“ Belohnungen erhalten. \n2. “Reise-Modus“ ist dauerhaft geöffnet. \n3. Nachdem das “Erweiterte Reise“ freigeschaltet wurde, können nach Abschluss der Aufgaben zusätzliche Belohnungen erhalten werden. \n4. Bitte beachten: Das im Rahmen dieser Aktivität freigeschaltete “Erweiterte Reise“ ist nur innerhalb dieser Aktivität gültig. Geheimnisträger sollten angemessen und verantwortungsbewusst konsumieren."
  },
  Activity_76218_ActivityName = {
    Text = "Ankunft-Reisebericht"
  },
  Activity_76218_ActivityTips = {
    Text = "Aktivitätsregeln: \n1. Geheimnisträger können nach Abschluss der vorgeschriebenen „Chronik“-Aufgaben im „Ankunft-Chronik“ Belohnungen erhalten. \n2. „Ankunft-Chronik“ ist dauerhaft geöffnet. \n3. Nachdem die „Erweiterte Chronik“ freigeschaltet wurde, erhält man nach Abschluss der Aufgaben zusätzliche Belohnungen. \n4. Bitte beachten: Die im Rahmen dieser Aktivität freigeschaltete „Erweiterte Chronik“ ist nur innerhalb dieser Aktivität gültig. Geheimnisträger sollten angemessen und verantwortungsvoll konsumieren."
  },
  Activity_77970_ActivityName = {Text = "Pollux"},
  Activity_77970_ActivityTips = {
    Text = "<Title:Aktionsregeln>\n· Während der “Pollux“-Aktion kann der Geheimnisträger unbegrenzt oft spezifische Ebenen mit einem vordefinierten Team, das Pollux enthält, spielen.\n· Während des Spielens der Aktions-Ebenen kann die Zusammensetzung der gerufenen Wesen im Team nicht geändert werden.\n<Title:Aktionsbelohnungen>\n· Nachdem die Ebenenherausforderung zum ersten Mal abgeschlossen wurde, kann im Aktionsinterface eine Probierbelohnung abgeholt werden."
  },
  Activity_77972_ActivityName = {
    Text = "Hypnotisches Shaggai"
  },
  Activity_77972_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n· Während der Aktivität „Hypnotische Bestie“ können Hüter unbegrenzt oft spezielle Ebenen mit vordefinierten Teams, die Clementine enthalten, spielen.\n· Während der Aktivitätsmissionen ist es nicht möglich, die erwachten Charaktere im Team während des Spiels zu ändern.\n<Title:Aktivitätsbelohnungen>\n· Nachdem eine Ebenenherausforderung zum ersten Mal erfolgreich abgeschlossen wurde, kann im Aktivitätsinterface eine Probierbelohnung abgeholt werden."
  },
  Activity_77974_ActivityName = {
    Text = "Mareel Glanz"
  },
  Activity_77974_ActivityTips = {
    Text = "<Title:Aktionsregeln>\n· Während der „Kaltlicht“-Aktion kann der Geheimnisträger unbegrenzt oft spezielle Ebenen mit einem vordefinierten Team, das Kepsant enthält, spielen.\n· Während der Aktions-Ebenen ist es nicht möglich, die aufgestandenen Wesen in der Kampfgruppe anzupassen.\n<Title:Aktionsbelohnungen>\n· Nachdem die Ebenenherausforderung zum ersten Mal erfolgreich abgeschlossen wurde, kann im Aktionsinterface eine Probierbelohnung abgeholt werden.\n"
  },
  Activity_77977_ActivityName = {
    Text = "Schneewittchen die Fee"
  },
  Activity_77977_ActivityTips = {
    Text = "<Title:Eventregeln>\nWährend des Events „Schneewittchen die Fee“ können Schutzherren vom System voreingestellte Aufstellungen, die „Caraboo“ enthalten, verwenden, um bestimmte Stufen unbegrenzt oft zu erleben.\n Beim Erleben von Event-Stufen können die Erwecker in der Aufstellung nicht angepasst werden.\n<Title:Eventbelohnungen>\nNach dem erstmaligen Abschließen der Stufenherausforderung können Testbelohnungen auf der Event-Oberfläche eingefordert werden."
  },
  Activity_77979_ActivityName = {
    Text = "Herr der Explosion"
  },
  Activity_77979_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n· Während der „Herrscher des Infernos“-Aktivität können Geheimnisträger unbegrenzt oft voreingestellte Systemteams mit Katyura in speziellen Ebenen verwenden.\n· Während des Aktivitätslevels kann die Formation im Team nicht geändert werden.\n<Title:Aktivitätsbelohnung>\n· Nachdem die Levelherausforderung erstmals erfolgreich abgeschlossen wurde, kann im Aktivitätsinterface eine Probierbelohnung abgeholt werden."
  },
  Activity_77980_ActivityName = {
    Text = "Tela Perpetua"
  },
  Activity_77980_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\nWährend der Veranstaltung „Das Netz Der Ewigkeit\" können die Schutzherren mit voreingestellten Teams, die Arachne enthalten, unendlich oft an den festgelegten Levels teilnehmen.\nWährend des Erlebnisses der Aktivitätslevels kann der Erweckte Körper im Team nicht angepasst werden.\n<Title:Aktivitätsbelohnungen>\nNach der erstmaligen Erfüllung der Levelherausforderung können die Testbelohnungen im Veranstaltungsfenster abgeholt werden."
  },
  Activity_77984_ActivityName = {Text = "Der Maler"},
  Activity_77984_ActivityTips = {
    Text = "<Title:Aktivitätsregeln>\n· Während der Aktivität “Zeichner“ können Geheimnisträger unbegrenzt die vorgegebenen Teams mit Pikman in den bestimmten Levels erleben. \n· Während des Erlebnisses in den Aktivitätslevels können die Erwachten im Team nicht angepasst werden. \n<Title:Aktivitätsbelohnungen>\n· Nach erstmaligem Bestehen der Level-Herausforderung können Belohnungen für das Probieren im Aktivitätsfenster abgeholt werden."
  },
