  Activity_80167_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des Events \"Seelenfänger\" können Hüter systemvorgesehene Teams verwenden, die Helot: Catena enthalten, um die vorgegebenen Level unendlich zu erfahren.\n·Bei der Erkundung der Eventlevel sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nach erfolgreichem Abschluss der Levelherausforderung zum ersten Mal können Spieler Probeprämien in der Eventoberfläche einlösen."
  },
  Activity_80311_ActivityName = {
    Text = "Erinnerungsgeschenk der Reise · Sternenkapitel II"
