  Activity_91356_ActivityName = {
    Text = "Reise in die Stadt der Toten"
  },
  Activity_91356_ActivityTips = {
    Text = "Ereignis Regeln:\n1. Hüter können Belohnungen in \"Verschwendete Stadt Reise\" nach Abschluss bestimmter Reiseaufgaben erhalten.\n2. \"Verschwendete Stadt Reise\" ist dauerhaft geöffnet.\n3. Nach Freischaltung der \"Fortgeschrittenen Reise\" können zusätzliche Belohnungen durch das Abschließen von Aufgaben erhalten werden.\n4. Bitte beachten: Die im Rahmen dieses Ereignisses freigeschaltete \"Fortgeschrittene Reise\" ist nur während dieses Ereignisses gültig. Hüter sollten vernünftig und umsichtig konsumieren."
  },
