  Activity_97297_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Queen of Thorns\"-Ereignisses können Hüter systempreset Teams nutzen, die Wanda enthalten, um festgelegte Levels unendlich zu erleben.\n·Beim Erleben der Ereignislevels sind Anpassungen an den Erwachern in der Teamaufstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Level-Herausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können Spieler im Ereignisinterface Testbelohnungen beanspruchen."
