  Activity_98445_ActivityTips = {
    Text = "<Title:Event Rules>\n·Während des \"Eternal Performer\"-Ereignisses können Hüter systemvorgesehene Teams, die Hameln einschließen, nutzen, um bestimmte Level unendlich zu erleben.\n·Bei der Erfahrung von Ereignislevels sind Anpassungen der Erwacher in der Teamausstellung nicht erlaubt.\n<Title:Event Rewards>\n·Nachdem die Levelherausforderung zum ersten Mal erfolgreich abgeschlossen wurde, können die Spieler im Ereignisinterface Testbelohnungen einfordern."
